"use client"

import { useRouter } from "next/navigation"
import { useEffect } from "react"
import { useAuth } from "@/hooks/use-auth"
import { Plus } from "@phosphor-icons/react"

export default function DashboardPage() {
  const router = useRouter()
  const { user, isAuthenticated, isLoading } = useAuth()

  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      router.replace("/login")
    }
  }, [isLoading, isAuthenticated, router])

  if (isLoading || !user) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-[#e0e0e0]">
        <p className="text-sm text-gray-500 animate-pulse">Carregando...</p>
      </div>
    )
  }

  // Texto simulado para bater perfeitamente com o layout "nonifubw..." da imagem 1
  const textPlaceholder = "nonifubwieygshbjklkmn bgyuiuyh gvbnswbofcbpaaiooooo ooooooooooocnwjebcw kec"

  return (
    <div className="flex min-h-screen bg-[#dcdcdc] relative font-sans">
      
      {/* Barra de Navegação Lateral Estilo Wireframe */}
      <aside className="w-20 bg-[#cfcfcf] flex flex-col items-center pt-24 gap-6 px-2 shadow-inner">
        {/* Ícone Marrom de Perfil no topo do menu */}
        <div className="w-10 h-10 bg-[#7c4d4d] rounded-sm cursor-pointer hover:opacity-80 transition-opacity" onClick={() => router.push('/dashboard/profile')} title="Perfil" />
        
        {/* Abas Roxas Laterais */}
        <div className="w-10 h-10 bg-[#540954] rounded-sm cursor-pointer hover:bg-[#6c126c]" />
        <div className="w-10 h-10 bg-[#540954] rounded-sm cursor-pointer hover:bg-[#6c126c]" />
        <div className="w-10 h-10 bg-[#540954] rounded-sm cursor-pointer hover:bg-[#6c126c]" />
      </aside>

      {/* Área Principal de Conteúdo */}
      <div className="flex-1 flex flex-col">
        
        {/* Topbar Customizada */}
        <header className="h-16 bg-[#e0e0e0] flex items-center justify-between px-6 relative border-b border-gray-300">
          {/* Canto cortado decorativo superior esquerdo */}
          <div className="absolute top-0 left-0 w-6 h-6 bg-[#7c4d4d] clip-corner" style={{ clipPath: 'polygon(0 0, 100% 0, 0 100%)' }} />
          
          {/* Caixa central escura de buscas/título */}
          <div className="mx-auto w-full max-w-xl h-7 bg-[#281330] rounded-full" />
          
          {/* Canto cortado decorativo superior direito */}
          <div className="absolute top-0 right-0 w-6 h-6 bg-[#7c4d4d]" style={{ clipPath: 'polygon(0 0, 100% 0, 100% 100%)' }} />
        </header>

        {/* Grid de Conteúdo Central da Home */}
        <main className="flex-1 bg-white m-4 rounded-tl-sm p-8 overflow-y-auto max-w-5xl w-full mx-auto shadow-sm">
          <div className="flex flex-col gap-12">
            
            {/* Bloco 1: Imagem Esquerda, Texto Direita */}
            <section className="grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
              <div className="h-48 bg-[#d9d9d9] rounded-md flex items-center justify-center shadow-inner">
                <span className="text-xs text-gray-400">[Placeholder Gráfico / Media]</span>
              </div>
              <div className="text-gray-800 font-mono text-sm leading-relaxed text-center md:text-left break-all">
                {textPlaceholder}
              </div>
            </section>

            {/* Bloco 2: Texto Esquerda, Imagem Direita (Ziguezague) */}
            <section className="grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
              <div className="text-gray-800 font-mono text-sm leading-relaxed text-center md:text-left break-all order-2 md:order-1">
                {textPlaceholder}
              </div>
              <div className="h-48 bg-[#d9d9d9] rounded-md flex items-center justify-center shadow-inner order-1 md:order-2">
                <span className="text-xs text-gray-400">[Placeholder Gráfico / Media]</span>
              </div>
            </section>

          </div>
        </main>
      </div>

      {/* Floating Action Button (Botão Flutuante Vermelho no canto direito inferior) */}
      <button 
        onClick={() => alert("Ação do botão flutuante clicada!")}
        className="absolute bottom-6 right-6 w-14 h-14 bg-[#a61212] hover:bg-[#bd1616] text-white rounded-full flex items-center justify-center shadow-lg transition-transform hover:scale-105 active:scale-95 focus:outline-none"
        title="Adicionar Novo"
      >
        <Plus size={28} weight="bold" />
      </button>
      
    </div>
  )
}